function create_map(e,o,n){const t={mapId:n,zoom:8,center:new google.maps.LatLng(e,o),mapTypeId:google.maps.MapTypeId.ROADMAP,mapTypeControl:!1,scaleControl:!1,streetViewControl:!1,rotateControl:!1,fullscreenControl:!1,draggable:!1,scrollwheel:!1,disableDoubleClickZoom:!1,zoomControl:!1};return new google.maps.Map(document.getElementById(n),t)}function update_marker_position(map,e,o,n,infoWindow,googleMapMarker){infoWindow&&infoWindow.close(),map&&(googleMapMarker&&googleMapMarker.setMap(null),googleMapMarker=new google.maps.marker.AdvancedMarkerElement({map:map,position:new google.maps.LatLng(e,o)}),(infoWindow=new google.maps.InfoWindow({content:'<span style="color:#111; text-align:center; display:block;" ><b>'+n+"</b> </span>"})).open(map,googleMapMarker))}function freightCalc(e,o,n,t,a,l){var s=new google.maps.LatLng(o,n),g=new google.maps.LatLng(t,a),r=new google.maps.DirectionsService;const c={origin:s,destination:g,travelMode:google.maps.TravelMode.DRIVING};r.route(c,function(o,n){n==google.maps.DirectionsStatus.OK?l(e,o.routes[0].legs[0].distance.text,o.routes[0].legs[0].distance.value/1e3,o.routes[0].legs[0].duration.text):console.log("No se pudo realizar el c&aacute;lculo de distancia")})}